/* One C source, any webgpu.h implementation (Dawn or wgpu-native), compute + readback.
 * Prints RESULT PASS and an FNV hash of the output; every backend/OS must print the same hash.
 *   plain build : link directly against Dawn or wgpu-native
 *   -DDLSHIM    : Cosmopolitan APE; loads the library named in argv[1] with cosmo_dlopen()
 *                 (dl_shim.h is generated by gen-shim.py from this file's wgpu* calls) */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <webgpu/webgpu.h>
#ifdef DLSHIM
#include "dl_shim.h"
#endif
#ifdef _WIN32
#include <windows.h>
#define SLEEP1() Sleep(1)
#else
#include <unistd.h>
#define SLEEP1() usleep(1000)
#endif

static WGPUInstance inst;
static WGPUAdapter adapter; static WGPUDevice device;
static volatile int done; static int status;

static void sv(WGPUStringView s){ if(s.data) fwrite(s.data,1,s.length==WGPU_STRLEN?strlen(s.data):s.length,stdout); }
static void on_adapter(WGPURequestAdapterStatus s, WGPUAdapter a, WGPUStringView m, void*u1, void*u2){ status=s; adapter=a; if(s!=1){printf("adapter err: ");sv(m);puts("");} done=1; }
static void on_device(WGPURequestDeviceStatus s, WGPUDevice d, WGPUStringView m, void*u1, void*u2){ status=s; device=d; if(s!=1){printf("device err: ");sv(m);puts("");} done=1; }
static void on_map(WGPUMapAsyncStatus s, WGPUStringView m, void*u1, void*u2){ status=s; done=1; }
static void pump(void){ int n=0; while(!done && n++<20000){ wgpuInstanceProcessEvents(inst); SLEEP1(); } }

int main(int argc,char**argv){
#ifdef DLSHIM
  { void*h=cosmo_dlopen(argc>1?argv[1]:"libwgpu_native.so",RTLD_NOW); if(!h){printf("dlopen failed: %s\n",cosmo_dlerror());return 8;} {int r=dl_load(h); if(r) return r;} }
#endif
  WGPUInstanceDescriptor id = WGPU_INSTANCE_DESCRIPTOR_INIT;
  inst = wgpuCreateInstance(&id);
  if(!inst){puts("FAIL create instance");return 1;}
  WGPURequestAdapterOptions ao = WGPU_REQUEST_ADAPTER_OPTIONS_INIT;
  WGPURequestAdapterCallbackInfo ci = WGPU_REQUEST_ADAPTER_CALLBACK_INFO_INIT;
  ci.mode = WGPUCallbackMode_AllowProcessEvents; ci.callback = on_adapter;
  done=0; wgpuInstanceRequestAdapter(inst,&ao,ci); pump();
  if(!adapter){puts("FAIL no adapter");return 2;}
  WGPUAdapterInfo info = WGPU_ADAPTER_INFO_INIT; wgpuAdapterGetInfo(adapter,&info);
  printf("adapter: backend=%d type=%d vendor=",info.backendType,info.adapterType); sv(info.vendor); printf(" device="); sv(info.device); printf(" desc="); sv(info.description); puts("");
  WGPUDeviceDescriptor dd = WGPU_DEVICE_DESCRIPTOR_INIT;
  WGPURequestDeviceCallbackInfo dci = WGPU_REQUEST_DEVICE_CALLBACK_INFO_INIT;
  dci.mode = WGPUCallbackMode_AllowProcessEvents; dci.callback = on_device;
  done=0; wgpuAdapterRequestDevice(adapter,&dd,dci); pump();
  if(!device){puts("FAIL no device");return 3;}
  WGPUQueue q = wgpuDeviceGetQueue(device);

  const char *wgsl = "@group(0) @binding(0) var<storage,read_write> d: array<u32>;\n"
    "@compute @workgroup_size(64) fn main(@builtin(global_invocation_id) g: vec3<u32>){ d[g.x] = g.x*g.x + 7u; }\n";
  WGPUShaderSourceWGSL w = WGPU_SHADER_SOURCE_WGSL_INIT; w.chain.sType = WGPUSType_ShaderSourceWGSL; w.code = (WGPUStringView){wgsl, strlen(wgsl)};
  WGPUShaderModuleDescriptor smd = WGPU_SHADER_MODULE_DESCRIPTOR_INIT; smd.nextInChain = &w.chain;
  WGPUShaderModule sm = wgpuDeviceCreateShaderModule(device,&smd);
  WGPUComputePipelineDescriptor cpd = WGPU_COMPUTE_PIPELINE_DESCRIPTOR_INIT;
  cpd.compute.module = sm; cpd.compute.entryPoint = (WGPUStringView){"main",4};
  WGPUComputePipeline p = wgpuDeviceCreateComputePipeline(device,&cpd);
  enum{N=256}; size_t bytes=N*4;
  WGPUBufferDescriptor bd = WGPU_BUFFER_DESCRIPTOR_INIT; bd.size=bytes; bd.usage=WGPUBufferUsage_Storage|WGPUBufferUsage_CopySrc;
  WGPUBuffer sb = wgpuDeviceCreateBuffer(device,&bd);
  bd.usage=WGPUBufferUsage_MapRead|WGPUBufferUsage_CopyDst; WGPUBuffer rb = wgpuDeviceCreateBuffer(device,&bd);
  WGPUBindGroupEntry be = WGPU_BIND_GROUP_ENTRY_INIT; be.binding=0; be.buffer=sb; be.size=bytes;
  WGPUBindGroupDescriptor bgd = WGPU_BIND_GROUP_DESCRIPTOR_INIT; bgd.layout=wgpuComputePipelineGetBindGroupLayout(p,0); bgd.entryCount=1; bgd.entries=&be;
  WGPUBindGroup bg = wgpuDeviceCreateBindGroup(device,&bgd);
  WGPUCommandEncoderDescriptor ed = WGPU_COMMAND_ENCODER_DESCRIPTOR_INIT;
  WGPUCommandEncoder e = wgpuDeviceCreateCommandEncoder(device,&ed);
  WGPUComputePassDescriptor pd = WGPU_COMPUTE_PASS_DESCRIPTOR_INIT;
  WGPUComputePassEncoder cp = wgpuCommandEncoderBeginComputePass(e,&pd);
  wgpuComputePassEncoderSetPipeline(cp,p); wgpuComputePassEncoderSetBindGroup(cp,0,bg,0,NULL);
  wgpuComputePassEncoderDispatchWorkgroups(cp,N/64,1,1); wgpuComputePassEncoderEnd(cp);
  wgpuCommandEncoderCopyBufferToBuffer(e,sb,0,rb,0,bytes);
  WGPUCommandBufferDescriptor cbd = WGPU_COMMAND_BUFFER_DESCRIPTOR_INIT;
  WGPUCommandBuffer cb = wgpuCommandEncoderFinish(e,&cbd); wgpuQueueSubmit(q,1,&cb);
  WGPUBufferMapCallbackInfo mi = WGPU_BUFFER_MAP_CALLBACK_INFO_INIT; mi.mode=WGPUCallbackMode_AllowProcessEvents; mi.callback=on_map;
  done=0; wgpuBufferMapAsync(rb,WGPUMapMode_Read,0,bytes,mi); pump();
  if(status!=WGPUMapAsyncStatus_Success){puts("FAIL map");return 4;}
  const uint32_t *r = wgpuBufferGetConstMappedRange(rb,0,bytes);
  uint64_t h=1469598103934665603ULL; int bad=0;
  for(uint32_t i=0;i<N;i++){ if(r[i]!=i*i+7) bad++; h=(h^r[i])*1099511628211ULL; }
  printf("compute N=%d mismatches=%d fnv=%016llx\n",N,bad,(unsigned long long)h);
  puts(bad?"RESULT FAIL":"RESULT PASS");
  return bad!=0;
}
